document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("roi-form");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("investment").value),t=parseFloat(document.getElementById("profit").value);if(0===n)return document.getElementById("roi-result").innerHTML="<p style='color:red;'>Investment amount cannot be zero.</p>",void 0;const r=(t-n)/n*100,o=t-n,s=e=>e.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:2,maximumFractionDigits:2});let i="";i=r>25?"Excellent return! This is an outstanding investment performance.":r>15?"Very good return. This investment performed well.":r>5?"Decent return. This investment was moderately successful.":r>0?"Positive return, but relatively low performance.":0===r?"Break-even. No profit or loss on this investment.":"Negative return. This investment resulted in a loss.",document.getElementById("roi-result").innerHTML=`\n      <h3>ROI Analysis Results:</h3>\n      <div style="background: #f5f5f5; padding: 1rem; border-radius: 5px; margin: 1rem 0;">\n        <p><strong>Return on Investment (ROI): ${r.toFixed(2)}%</strong></p>\n        <p><strong>Net Profit/Loss: ${s(o)}</strong></p>\n        <p><strong>Total Return: ${s(t)}</strong></p>\n        <p><strong>Original Investment: ${s(n)}</strong></p>\n      </div>\n      <p><em>${i}</em></p>\n    `})});